56	            + " claim.period_number, claim.due_by, COALESCE(corrected.claimed_on, claim.claimed_on) AS rounds_on,"
57	            + " claim.deferred_until, claim.proofs, claim.split_from, claim.locked_by, claim.late_entry, claim.reminded_on, claim.ref, claim.tags, claim.tags_ever, claim.batch, (claim.status IN ('OPEN', 'VOID') AND claim.deferred_until IS NOT NULL AND claim.deferred_until >"
58	            + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE)) AS deferred FROM claim"
59	            + " LEFT JOIN claim corrected ON corrected.sheet = claim.sheet AND "
60	            + " COALESCE(corrected.period_number, CAST(corrected.number_on_sheet AS VARCHAR)) = claim.corrects";
61	
62	    // The place after every claim listed on the sheet (bound to the sheet), so the claim lists newest.
63	    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(l.listed), 0) + 1 FROM claim l WHERE l.sheet = ?)";
64	
65	    private final JdbcTemplate jdbc;
66	
67	    public Claims(JdbcTemplate jdbc) {
68	        this.jdbc = jdbc;
69	    }
70	
71	    private static final String LOG = "SELECT claim, status, by_user, on_date, due FROM claim_log WHERE sheet = ?";
72	
73	    private static final String COMMENTS = "SELECT claim, by_user, on_date, text FROM claim_comment WHERE sheet = ?";
74	
75	    /** Every claim on the sheet, newest first. */
76	    public List<Claim> list(String sheet) {
77	        return withComments(withLogs(sheet, jdbc.query(COLUMNS + " WHERE claim.sheet = ? ORDER BY claim.listed DESC, claim.id DESC", ROW, sheet),
78	                jdbc.query(LOG + " ORDER BY id", LOG_ROW, sheet)), jdbc.query(COMMENTS + " ORDER BY id", COMMENT_ROW, sheet));
79	    }
80	
81	    public Claim find(String sheet, long id) {
82	        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ? AND claim.id = ?", ROW, sheet, id);
83	        return found.isEmpty() ? null
84	                : withComments(withLogs(sheet, found, jdbc.query(LOG + " AND claim = ? ORDER BY id", LOG_ROW, sheet, id)),
85	                        jdbc.query(COMMENTS + " AND claim = ? ORDER BY id", COMMENT_ROW, sheet, id)).get(0);
86	    }
87	
88	    private record Commented(long claim, ClaimComment comment) {
89	    }
90	
91	    private static final RowMapper<Commented> COMMENT_ROW = (rs, i) -> new Commented(rs.getLong("claim"),
92	            new ClaimComment(rs.getString("by_user"), rs.getDate("on_date").toLocalDate().toString(), rs.getString("text")));
93	
94	    /** The claims, each with its own comments (in the order written). */
95	    private static List<Claim> withComments(List<Claim> found, List<Commented> commented) {
96	        Map<Long, List<ClaimComment>> comments = new HashMap<>();
97	        for (Commented c : commented) {
98	            comments.computeIfAbsent(c.claim(), k -> new ArrayList<>()).add(c.comment());
99	        }
100	        return found.stream().map(c -> c.withComments(comments.getOrDefault(c.id(), List.of()))).toList();
101	    }
102	
103	    /** Adds a comment to the claim, by the user on the date (the sheet's today). */
104	    public void comment(String sheet, long id, String user, LocalDate on, String text) {
105	        jdbc.update("INSERT INTO claim_comment (sheet, claim, by_user, on_date, text) VALUES (?, ?, ?, ?, ?)",
106	                sheet, id, user, Date.valueOf(on), text);
107	    }
108	
109	    private record Logged(long claim, ClaimLogLine line) {
110	    }
111	
112	    private static final RowMapper<Logged> LOG_ROW = (rs, i) -> new Logged(rs.getLong("claim"),
113	            new ClaimLogLine(ClaimStatus.valueOf(rs.getString("status")), rs.getString("by_user"),
114	                    rs.getDate("on_date").toLocalDate().toString(), rs.getString("due")));
115	
116	    /** The claims, each with its own lines of the status log (oldest first). */
117	    private static List<Claim> withLogs(String sheet, List<Claim> found, List<Logged> logged) {
118	        Map<Long, List<ClaimLogLine>> lines = new HashMap<>();
119	        for (Logged l : logged) {
120	            lines.computeIfAbsent(l.claim(), k -> new ArrayList<>()).add(l.line());
121	        }
122	        return found.stream().map(c -> c.withLog(lines.getOrDefault(c.id(), List.of()))).toList();
123	    }
124	
125	    /** The claim showing this number on the sheet (within its period, or on the sheet), or null when none does. */
126	    public Claim findByNumber(String sheet, String number) {
127	        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ?"
128	                + " AND COALESCE(claim.period_number, CAST(claim.number_on_sheet AS VARCHAR)) = ?", ROW, sheet, number);
129	        return found.isEmpty() ? null : found.get(0);
130	    }
131	
132	    /**
133	     * Adds the claim with its due-by and the terms it was fixed with; the due-by moves after only when a holiday is
134	     * added (see {@link #refixDueBy}); returns its id.
135	     */
136	    public long add(String sheet, long person, ClaimInput input, LocalDate dueBy, int terms) {
137	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
138	        jdbc.update(con -> {
139	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, corrects, due_by, ref, tags, tags_ever, due_terms, listed)"
140	                    + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", new String[] { "id" });
141	            ps.setString(1, sheet);
142	            ps.setLong(2, person);
143	            ps.setBigDecimal(3, input.amount());
144	            ps.setDate(4, Date.valueOf(input.date()));
145	            ps.setString(5, input.note());
146	            ps.setString(6, input.corrects());
147	            ps.setDate(7, Date.valueOf(dueBy));
148	            ps.setString(8, input.ref());
149	            ps.setString(9, kept(input.tags()));
150	            ps.setString(10, kept(input.tags()));
151	            ps.setInt(11, terms);
152	            ps.setString(12, sheet);
153	            return ps;
154	        }, keys);
155	        return keys.getKey().longValue();
156	    }
157	
158	    private record Fixed(long id, LocalDate date, int terms) {
159	    }
160	
161	    /**
162	     * Re-fixes the due-by of every claim on the sheet that is not SETTLED or VOID and whose due-by is on or after the
163	     * date: the terms-th business day after its date, with the terms it was fixed with, skipping weekends and the
164	     * holidays given.
165	     */
166	    public void refixDueBy(String sheet, LocalDate from, Set<LocalDate> holidays) {
167	        List<Fixed> fixed = jdbc.query("SELECT id, claimed_on, due_terms FROM claim WHERE sheet = ?"
168	                + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ?",
169	                (rs, i) -> new Fixed(rs.getLong("id"), rs.getDate("claimed_on").toLocalDate(), rs.getInt("due_terms")),
170	                sheet, Date.valueOf(from));
171	        for (Fixed claim : fixed) {
172	            LocalDate dueBy = Holidays.businessDaysAfter(claim.date(), claim.terms(), holidays);
173	            jdbc.update("UPDATE claim SET due_by = ? WHERE sheet = ? AND id = ?", Date.valueOf(dueBy), sheet, claim.id());
174	        }
175	    }
176	
177	    /** Whether a claim on the sheet other than the one excluded (null for none) has the reference, ignoring case. */
178	    public boolean refUsed(String sheet, String ref, Long excluded) {
179	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
180	                Integer.class, sheet, ref, excluded == null ? -1L : excluded);
181	        return n != null && n > 0;
182	    }
183	
184	    /** Marks the claim a late entry: added while the period its due-by falls in was soft-closed. */
185	    public void setLateEntry(String sheet, long id) {
186	        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet = ? AND id = ?", sheet, id);
187	    }
188	
189	    /**
190	     * Adds the OPEN claim split off another: the amount, with the date, note and tags of the claim it was split from
191	     * (by the number that claim shows), opened by the user, with its due-by fixed now; returns its id.
192	     */
193	    public long addSplit(String sheet, long person, BigDecimal amount, LocalDate date, String note, List<String> tags,
194	            LocalDate dueBy, int terms, String splitFrom, String openedBy) {
195	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
196	        jdbc.update(con -> {
197	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, due_by, status,"
198	                    + " split_from, opened_by, tags, tags_ever, due_terms, listed) VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, ?, ?, ?, "
199	                    + NEXT_LISTED + ")",
200	                    new String[] { "id" });
201	            ps.setString(1, sheet);
202	            ps.setLong(2, person);
203	            ps.setBigDecimal(3, amount);
204	            ps.setDate(4, Date.valueOf(date));
205	            ps.setString(5, note);
206	            ps.setDate(6, Date.valueOf(dueBy));
207	            ps.setString(7, splitFrom);
208	            ps.setString(8, openedBy);
209	            ps.setString(9, kept(tags));
210	            ps.setString(10, kept(tags));
211	            ps.setInt(11, terms);
212	            ps.setString(12, sheet);
213	            return ps;
214	        }, keys);
215	        return keys.getKey().longValue();
216	    }
217	
218	    /**
219	     * Leaves an OPEN claim the rest of its amount once split, unbound from any statement; conditional on the
220	     * amount read and on it still being OPEN and not deferred: false when it no longer is.
221	     */
222	    public boolean split(String sheet, long id, BigDecimal was, BigDecimal rest) {
223	        return jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL WHERE sheet = ? AND id = ?"
224	                + " AND status = 'OPEN' AND amount = ? AND (deferred_until IS NULL OR deferred_until <="
225	                + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE))",
226	                rest, sheet, id, was) == 1;
227	    }
228	
229	    /**
230	     * Edits a draft claim not locked by another user's editor, releasing any lock on it and recording the user as its
231	     * last editor: false when it is no longer a draft, or another user's editor holds it. The tags it carried before stay among those it has ever carried.
232	     */
233	    public boolean update(String sheet, long id, ClaimInput input, List<String> tagsEver, String user) {
234	        List<String> ever = Stream.concat(tagsEver.stream(), input.tags().stream()).distinct().sorted().toList();
235	        return jdbc.update(
236	                "UPDATE claim SET amount = ?, claimed_on = ?, note = ?, corrects = ?, ref = ?, tags = ?, tags_ever = ?, locked_by = NULL, edited_by = ?"
237	                        + " WHERE sheet = ? AND id = ? AND status = 'DRAFT' AND (locked_by IS NULL OR locked_by = ?)",
238	                input.amount(), Date.valueOf(input.date()), input.note(), input.corrects(), input.ref(), kept(input.tags()),
239	                kept(ever), user, sheet, id, user) == 1;
240	    }
241	
242	    /** Marks the claim settled by the bulk settle batch with the number; null when settled one at a time. */
243	    public void setBatch(String sheet, long id, Integer batch) {
244	        jdbc.update("UPDATE claim SET batch = ? WHERE sheet = ? AND id = ?", batch, sheet, id);
245	    }
246	
247	    /** The user who last edited the claim (through its form or its amount entry); null when never edited. */
248	    public String editedBy(String sheet, long id) {
249	        return jdbc.query("SELECT edited_by FROM claim WHERE sheet = ? AND id = ?",
250	                rs -> rs.next() ? rs.getString(1) : null, sheet, id);
251	    }
252	
253	    /**
254	     * Locks a draft claim for the user's editor, releasing any other claim the user's editor held on the sheet:
255	     * false when it is no longer a draft, or another user's editor holds it.
256	     */
257	    public boolean lock(String sheet, long id, String user) {
258	        if (jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet = ? AND id = ? AND status = 'DRAFT'"
259	                + " AND (locked_by IS NULL OR locked_by = ?)", user, sheet, id, user) != 1) {
260	            return false;
261	        }
262	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id <> ? AND locked_by = ?", sheet, id, user);
263	        return true;
264	    }
265	
266	    /** Releases the claim's lock when the user's editor holds it. */
267	    public void unlock(String sheet, long id, String user) {
268	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id = ? AND locked_by = ?", sheet, id, user);
269	    }
270	
271	    /** Releases every lock on the sheet's claims, as when its today changes. */
272	    public void unlockAll(String sheet) {
273	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND locked_by IS NOT NULL", sheet);
274	    }
275	
276	    /**
277	     * Moves the claim of the person and status it was read with to another person, unbound from any statement and
278	     * listed as the sheet's newest: false when it no longer has that person or status.
279	     */
280	    public boolean reassign(String sheet, long id, long from, ClaimStatus status, long to) {
281	        return jdbc.update("UPDATE claim SET person = ?, stated = FALSE, stated_due = NULL, listed = " + NEXT_LISTED
282	                + " WHERE sheet = ? AND id = ? AND person = ? AND status = ?", to, sheet, sheet, id, from,
283	                status.name()) == 1;
284	    }
285	
286	    /**
287	     * Moves the claim of the status and date it was read with to another date, keeping its due-by and any figure its
288	     * statement bound: false when it no longer has that status or date.
289	     */
290	    public boolean redate(String sheet, long id, ClaimStatus status, LocalDate was, LocalDate date) {
291	        return jdbc.update("UPDATE claim SET claimed_on = ? WHERE sheet = ? AND id = ? AND status = ? AND claimed_on = ?",
292	                Date.valueOf(date), sheet, id, status.name(), Date.valueOf(was)) == 1;
293	    }
294	
295	    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
296	    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
297	        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
298	                id, from.name()) == 1;
299	    }
300	
301	    /** Defers an OPEN claim until the date: false when it is no longer OPEN. */
302	    public boolean defer(String sheet, long id, LocalDate until) {
303	        return jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet = ? AND id = ? AND status = 'OPEN'",
304	                Date.valueOf(until), sheet, id) == 1;
305	    }
306	
307	    /**
308	     * Reminds an OPEN or PENDING claim on the date (the sheet's today), conditional on its status read and on it not
309	     * yet being reminded that day: false when it was not.
310	     */
311	    public boolean remind(String sheet, long id, ClaimStatus status, LocalDate today) {
312	        return jdbc.update("UPDATE claim SET reminded_on = ? WHERE sheet = ? AND id = ? AND status = ?"
313	                + " AND (reminded_on IS NULL OR reminded_on <> ?)", Date.valueOf(today), sheet, id, status.name(),
314	                Date.valueOf(today)) == 1;
315	    }
316	
317	    /**
318	     * Raises the claim's proofs count by one, conditional on the status and count read, so a concurrent change by
319	     * another user is refused, not overwritten: false when it was not.
320	     */
321	    public boolean addProof(String sheet, long id, ClaimStatus status, int was) {
322	        return jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet = ? AND id = ? AND status = ? AND proofs = ?",
323	                sheet, id, status.name(), was) == 1;
324	    }
325	
326	    /** Fixes the claim's due as it is settled, or leaves none with null. */
327	    public void setSettledDue(String sheet, long id, BigDecimal due) {
328	        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
329	    }
330	
331	    /**
332	     * Re-fixes a SETTLED claim's due (null for none), conditional on the due read, so a concurrent change by another
333	     * user is refused, not overwritten; false when it was not.
334	     */
335	    public boolean resettle(String sheet, long id, BigDecimal was, BigDecimal due) {
336	        return jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ? AND status = ?"
337	                + " AND settled_due IS NOT DISTINCT FROM ?", due, sheet, id, ClaimStatus.SETTLED.name(), was) == 1;
338	    }
339	
340	    /** Binds the claim to a statement's figure (null when its grade had no rate), or unbinds it when not stated. */
341	    public void setStated(String sheet, long id, boolean stated, BigDecimal due) {
342	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet = ? AND id = ?", stated, due, sheet, id);
343	    }
344	
345	    /** Unbinds every claim of the person bound by their last statement, so each is live again. */
346	    public void unbindPerson(String sheet, long person) {
347	        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet = ? AND person = ? AND stated",
348	                sheet, person);
349	    }
350	
351	    /** Records the user who opened the claim. */
352	    public void setOpenedBy(String sheet, long id, String user) {
353	        jdbc.update("UPDATE claim SET opened_by = ? WHERE sheet = ? AND id = ?", user, sheet, id);
354	    }
355	
356	    /** Sets the claim's number on the sheet, or clears it with null. */
357	    public void setNumber(String sheet, long id, Integer number) {
358	        jdbc.update("UPDATE claim SET number_on_sheet = ? WHERE sheet = ? AND id = ?", number, sheet, id);
359	    }
360	
361	    /** Sets the claim's number within its period. */
362	    public void setPeriodNumber(String sheet, long id, String periodNumber) {
363	        jdbc.update("UPDATE claim SET period_number = ? WHERE sheet = ? AND id = ?", periodNumber, sheet, id);
364	    }
365	
366	    /**
367	     * Takes the next number in the sheet's period of the name ("" for the claims in no period): 1 first, then 2,
368	     * and so on, each period counting on its own. Locked as {@link #nextNumber}.
369	     */
370	    public int nextPeriodNumber(String sheet, String period) {
371	        while (true) {
372	            if (jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet = ? AND period = ?",
373	                    sheet, period) == 1) {
374	                return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet = ? AND period = ?",
375	                        Integer.class, sheet, period);
376	            }
377	            try {
378	                jdbc.update("INSERT INTO claim_period_number (sheet, period, last_number) VALUES (?, ?, 1)", sheet, period);
379	                return 1;
380	            } catch (DuplicateKeyException raced) {
381	                // Another user took the period's first number at the same moment: take the one after it.
382	            }
383	        }
384	    }
385	
386	    /**
387	     * Takes the next number of the sheet-wide sequence the sheet shares with the other sheets of its tree: the one
388	     * after the last number given on any of them (1 when none has given one), recorded as the sheet's last number.
389	     * The counter rows of the whole tree stay locked until the transaction ends, so two claims opened at once
390	     * anywhere in the tree get different numbers.
391	     */
392	    public int nextNumber(String sheet, List<String> tree) {
393	        try {
394	            jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 0)", sheet);
395	        } catch (DuplicateKeyException exists) {
396	            // The sheet has given a number already: its counter is in place.
397	        }
398	        java.util.TreeSet<String> sheets = new java.util.TreeSet<>(tree);
399	        sheets.add(sheet);
400	        String in = String.join(", ", java.util.Collections.nCopies(sheets.size(), "?"));
401	        List<Integer> lasts = jdbc.queryForList("SELECT last_number FROM claim_number WHERE sheet IN (" + in
402	                + ") ORDER BY sheet FOR UPDATE", Integer.class, sheets.toArray());
403	        int next = lasts.stream().mapToInt(Integer::intValue).max().orElse(0) + 1;
404	        jdbc.update("UPDATE claim_number SET last_number = ? WHERE sheet = ?", next, sheet);
405	        return next;
406	    }
407	}
