# Validate before load so an invalid body is a 400, not masked by a 404. Responds with the sheet's claims.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|\\S{1,200}-\\d{1,9}");

    public void validate(@PathVariable("sheet") String sheet, @RequestBody ClaimRequest request, Settings settings,
            Out<ClaimInput> body) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        String date = request == null || request.date() == null ? "" : request.date().trim();
        String note = request == null || request.note() == null ? "" : request.note().trim();
        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
        String ref = request == null || request.ref() == null ? "" : request.ref().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals");
        }
        // A negative amount is a correction: it must name, by the number it shows (on the sheet, or
        // within its period: <period>-<n>), the claim it corrects; no other claim may.
        BigDecimal value = new BigDecimal(amount);
        if (value.signum() < 0 && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("A negative amount must name the number of the claim it corrects");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim");
        }
        LocalDate on;
        try {
            on = date.isEmpty() ? settings.entryDay(sheet) : LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Not a valid date: " + date);
        }
        body.set(new ClaimInput(value, on, note, value.signum() < 0 ? numbered(corrects) : null,
                ref.isEmpty() ? null : ref, ClaimInput.tagsOf(request == null ? null : request.tags())));
    }

    /** The number as a claim shows it: a number on the sheet without leading zeros, a period number as given. */
    private static String numbered(String corrects) {
        return corrects.chars().allMatch(Character::isDigit) ? Integer.toString(Integer.parseInt(corrects)) : corrects;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SaveClaim {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
            @Val ClaimInput input, Claims claims, People people, Periods periods, Audit audit, Rollup rollup)
            throws InvalidClaimException {
        // A claim due inside a closed period may not be edited; an edit leaves its due-by, so its period, as it is.
        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
            throw new InvalidClaimException("A claim due inside a closed period may not be edited");
        }
        // Only a draft may be edited: an open claim is voided and a new one added instead.
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be edited; only a DRAFT can");
        }
        Person owner = people.find(sheet, claim.person());
        if (owner.retiredBefore(input.date())) {
            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
        }
        input.checkCorrects(sheet, owner.id(), claims);
        input.checkRef(sheet, claim.id(), claims);
        Rollup.Snapshot before = rollup.take(sheet);
        if (claim.lockedBy() != null && !claim.lockedBy().equals(user)) {
            throw new InvalidClaimException("The claim is being edited by " + claim.lockedBy());
        }
        // Conditional on the claim still being a draft and not locked by another user's editor, so one another user
        // opened or locked meanwhile is refused; the save releases the lock.
        if (!claims.update(sheet, claim.id(), input, claim.tagsEver(), user)) {
            throw new InvalidClaimException("The claim is no longer a DRAFT, or another user is editing it");
        }
        audit.record("CLAIM_EDITED sheet=" + sheet + " by=" + user + " " + input.auditFields(owner.name()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheet") String sheet, @PathVariable("claim") long claim, Claims claims,
            Out<Claim> loaded) throws ClaimNotFoundException {
        Claim found = claims.find(sheet, claim);
        if (found == null) {
            throw new ClaimNotFoundException(claim);
        }
        loaded.set(found);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

/**
 * A validated claim body: a blank date already defaulted to the sheet's entry date (none set: its today); a negative amount (a correction) with
 * the number the claim it corrects shows (on the sheet, or within its period), which is null for any other claim; and its
 * external reference, trimmed (null when blank); and its tags, each trimmed and lower-cased, repeats dropped, sorted.
 */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref, List<String> tags) {

    public ClaimInput(BigDecimal amount, LocalDate date, String note) {
        this(amount, date, note, null, null);
    }

    public ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref) {
        this(amount, date, note, corrects, ref, List.of());
    }

    /** The tags of a comma separated text: each trimmed and lower-cased, blanks and repeats dropped, sorted. */
    public static List<String> tagsOf(String text) {
        return text == null ? List.of()
                : Arrays.stream(text.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
                        .distinct().sorted().toList();
    }

    /**
     * The audit fields of the claim as added: {@link #auditFields} then ref=<reference> when it has one, then
     * tags=<comma separated, sorted> when it has any.
     */
    public String addedAuditFields(String person) {
        return auditFields(person) + (ref == null ? "" : " ref=" + ref)
                + (tags.isEmpty() ? "" : " tags=" + String.join(",", tags));
    }

    /** Refuses a reference another claim on the sheet (any but the one excluded, null for none) already has, ignoring case. */
    public void checkRef(String sheet, Long excluded, Claims claims) throws InvalidClaimException {
        if (ref != null && claims.refUsed(sheet, ref, excluded)) {
            throw new InvalidClaimException("The reference " + ref + " is already used on the sheet");
        }
    }

    /** The audit fields of this claim for the named person: amount as the screen shows it, ISO date. */
    public String auditFields(String person) {
        return "person=" + person + " amount=" + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + " date=" + date;
    }

    /** Refuses a correction unless the claim it names is a SETTLED claim of the same person. */
    public void checkCorrects(String sheet, long person, Claims claims) throws InvalidClaimException {
        if (corrects == null) {
            return;
        }
        Claim corrected = claims.findByNumber(sheet, corrects);
        if (corrected == null || corrected.person() != person || corrected.status() != ClaimStatus.SETTLED) {
            throw new InvalidClaimException("A correction must name a SETTLED claim of the same person");
        }
    }
}
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheet}/people/{person}/claims and PUT /api/sheets/{sheet}/claims/{claim}. */
public record ClaimRequest(String amount, String date, String note, String corrects, String ref, String tags) {
