629	      {remindMutation.isError && (
630	        <span data-testid="claim-error" role="alert">
631	          {' '}A {claim.status} claim cannot be reminded (only an OPEN or PENDING claim, and only once per sheet-today).
632	        </span>
633	      )}
634	      {redateMutation.isError && (
635	        <span data-testid="claim-error" role="alert">
636	          {' '}A {claim.status} claim cannot be re-dated (only a steward re-dates, only an OPEN or PENDING claim outside a closed period, and only to a date outside a closed period, on or before its person's retirement).
637	        </span>
638	      )}
639	      {proofMutation.isError && (
640	        <span data-testid="claim-error" role="alert">
641	          {' '}A {claim.status} claim cannot be given a proof (not a SETTLED or VOID claim, nor one due inside a closed period).
642	        </span>
643	      )}
644	      {commentMutation.isError && (
645	        <span data-testid="claim-error" role="alert">
646	          {' '}This comment cannot be added: it may not be empty, and a viewer, an archived sheet or the as-of view changes nothing.
647	        </span>
648	      )}
649	      {splitMutation.isError && (
650	        <span data-testid="claim-error" role="alert">
651	          {' '}A {claim.status} claim cannot be split (only an OPEN claim, not deferred nor due inside a closed period, by a role that may open a claim, and only an amount more than 0.00 and less than the claim's).
652	        </span>
653	      )}
654	      {inlineMutation.isError && (
655	        <span data-testid="claim-error" role="alert">
656	          {' '}This amount cannot be saved: it needs up to two decimals (a negative one must be a correction), and only a DRAFT outside a closed period can be edited, not while another user has its editor open, nor by a viewer.
657	        </span>
658	      )}
659	      {move.isError && (
660	        <span data-testid="claim-error" role="alert">
661	          {' '}A {claim.status} claim cannot be reassigned (only a role the permission matrix lets, by default a steward, moves a claim, and only a DRAFT, OPEN or PENDING one, to another person).
662	        </span>
663	      )}
664	    </li>
665	  );
666	}
